+    @Test
+    fun `long list after terminal operation should be reported`() {
+        val code = """
+            fun main() {
+                listOf(1, 2, 3)
+                    .groupBy { "test" }
+                    .map { (a, b) -> a to b }
+                    .filter { (0..1).random() == 1  }
+                    .take(2)
+            }
+        """.trimIndent()
+        assertThat(subject.lintWithContext(env, code)).hasSize(1)
+    }
